a:1:{s:57:"../../../modules/Integration/Application/OutboxWorker.php";a:1:{i:0;O:49:"PHPStan\Dependency\ExportedNode\ExportedClassNode":10:{s:55:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀name";s:44:"Modules\Integration\Application\OutboxWorker";s:57:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:621:"/**
